local a=require"system.hardware"local b={...}local c=b[2]and a.wrap(b[2])or a.find("drive")if not c then if b[2]then error("Could not find drive named "..b[2])else error("Could not find any attached drives")end end;if b[1]=="play"then local d=c.state;if not d then error("No disc in drive")elseif not d.audio then error("Disc in drive is not a record")end;c.play()print("Playing '"..d.audio.."'")elseif b[1]=="stop"then c.stop()else error("Usage: dj <play|stop> [drive]")end
